/// Recursive DFS traversal that collects node counts, error counts, and
/// nesting depths in a single pass.
fn walk_tree(
    &self,
    node: Node,
    metrics: &mut TreeMetrics,
    paren_depth: usize,
    function_depth: usize,
    statement_depth: usize,
) {
    metrics.node_count += 1;

