#[cfg(test)]
mod tests {
    use super::*;
    use mlt_core::Config;
    use tree_sitter::Parser;

    /// Parse MATLAB source and return the tree.
    fn parse(source: &str) -> tree_sitter::Tree {
        let mut parser = Parser::new();
