#[test]
fn debug_tree() {
    for src in [
        "x = [1 2 3];\n",
        "c = {1 2};\n",
        "function f()\nfor i = 1:10\nx = i;\nend\nend\n",
        "if (x > 0)\n    y = 1;\nend\n",
        "disp('hello');\n",
        "foo(a b);\n",
    ] {
        println!("===== SRC: {src:?} =====");
        let tree = parse(src);
        fn walk(node: tree_sitter::Node, src: &str, depth: usize) {
            let text: String = src[node.byte_range()]
                .chars()
                .filter(|c| !c.is_control())
                .collect();
            println!("{}{} [{}-{}] {:?}", "  ".repeat(depth), node.kind(), node.start_byte(), node.end_byte(), text);
            let mut c = node.walk();
            for ch in node.children(&mut c) {
                walk(ch, src, depth + 1);
            }
        }
        walk(tree.root_node(), src, 0);
        let tree2 = parse(src);
        fn fields(node: tree_sitter::Node, src: &str, depth: usize) {
            let text: String = src[node.byte_range()].chars().filter(|c| !c.is_control()).collect();
            let mut field_names = Vec::new();
            for i in 0..node.child_count() {
                if let Some(f) = node.field_name_for_child(i as u32) {
                    if let Some(ch) = node.child(i) {
                        field_names.push(format!("{f}={}", ch.kind()));
                    }
                }
            }
            if !field_names.is_empty() {
                println!("{}{} fields: {}", "  ".repeat(depth), node.kind(), field_names.join(", "));
            }
            let mut c2 = node.walk();
            for ch in node.children(&mut c2) { fields(ch, src, depth + 1); }
        }
        fields(tree2.root_node(), src, 0);
        let diags = lint(src);
        println!("DIAGS: {:?}", diags);
    }
    panic!("debug");
}

