/// Parse a severity string into (enabled, Option<Severity>).
///
/// "off" → (false, None)
/// "error" → (true, Some(Error))
/// "warn" → (true, Some(Warning))
/// "info" → (true, Some(Info))
fn parse_severity_string(s: &str) -> Result<(bool, Option<Severity>), ConfigError> {
    match s.to_lowercase().as_str() {
