//! Shared test utilities for rule module tests.

#![cfg(test)]

use mlt_core::{Diagnostic, FileContext, NodeContext, Rule};
use tree_sitter::{Node, Parser};

/// Parse MATLAB source and return the tree.
pub fn parse(source: &str) -> tree_sitter::Tree {
    let mut parser = Parser::new();
    parser
        .set_language(&tree_sitter_matlab::LANGUAGE.into())
        .expect("failed to load tree-sitter-matlab");
    parser.parse(source, None).expect("parse failed")
}

/// A FileContext with a fixed test path.
pub fn file_ctx<'a>(tree: &'a tree_sitter::Tree, source: &'a str) -> FileContext<'a> {
    FileContext {
        tree,
        source,
        file_path: std::path::Path::new("test.m"),
    }
}

/// Run the rule's node-level `check()` over every node in the tree,
/// mimicking the Linter's DFS dispatch. Returns combined diagnostics.
pub fn lint_nodes(rule: &dyn Rule, source: &str) -> Vec<Diagnostic> {
    let tree = parse(source);
    let path = std::path::Path::new("test.m");
    let target: Vec<&str> = rule.target_node_types().iter().copied().collect();
    let mut diagnostics = Vec::new();

    fn walk(
        node: Node,
        source: &str,
        path: &std::path::Path,
        target: &[&str],
        rule: &dyn Rule,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        if target.contains(&node.kind()) {
            let ctx = NodeContext { node, source, file_path: path };
            diagnostics.extend(rule.check(&ctx));
        }
        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            walk(child, source, path, target, rule, diagnostics);
        }
    }

    let root = tree.root_node();
    walk(root, source, path, &target, rule, &mut diagnostics);
    diagnostics
}
```

