fn check_function_call(
    &self,
    ctx: &NodeContext,
    results: &mut Vec<Diagnostic>,
) {
    let node = ctx.node;
    let source = ctx.source;

    let func_name = match node.child_by_field_name("name") {
        Some(n) => &source[n.start_byte()..n.end_byte()],
