/// Whether `node`'s attributes (direct children) include both `a` and `b`.
fn has_attributes_with_both(
    node: Node,
    a: &str,
    b: &str,
    source: &str,
) -> bool {
    let attrs = attribute_names(node, source);
    attrs.iter().any(|x| x == a) && attrs.iter().any(|x| x == b)
}

