    fn fcnva_comma_separated_not_fires() {
        let d = lint_file(&*engine(), "f('Name', value);\n");
        assert!(!has_id(&d, "FCNVA"), "got: {d:?}");
    }

    #[test]
    fn impkey_reserved_import_fires() {
        let d = lint_file(&*engine(), "import if;\n");
        assert!(has_id(&d, "IMPKEY"), "got: {d:?}");
    }

