use tree_sitter::Parser;
fn dump(node: tree_sitter::Node, src: &str, depth: usize) {
    let indent = "  ".repeat(depth);
    let text = &src[node.start_byte()..node.end_byte()];
    let t = text.replace('\n', "\\n");
    let truncated = if t.len() > 34 { format!("{}...", &t[..34]) } else { t };
    println!("{indent}{} {:?}", node.kind(), truncated);
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) { dump(child, src, depth + 1); }
}
fn main() {
    for s in ["x = 1;\nfunction y = helper(x)\n y = x;\nend\n",
              "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa = 1;\n",
              "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n"] {
        let mut p = Parser::new();
        p.set_language(&tree_sitter_matlab::LANGUAGE.into()).unwrap();
        let tree = p.parse(s, None).unwrap();
        println!("===== {s:?} =====");
        dump(tree.root_node(), s, 0);
        println!();
    }
}
