//! # 4.5-C: Forward-compat version gates, global/import scope, and unset vars
//!
//! These generic compatibility checks detect language features gated on a
//! minimum MATLAB version (forward compatibility) plus a few scope/unset
//! checks that the name-lookup table cannot match:
//!
//! - **FCLEN/FCCPV/FCDQS/FCFAV/FCHBL/FCLFS/FCNVA** — language constructs that
//!   require a newer MATLAB release.
//! - **REDEFGI/REDEFGG** — `global` declaration misuse.
//! - **NSTIMP** — nested functions inheriting import statements.
//! - **IMPIVD/IMPKEY** — malformed / reserved-word `import` arguments.
//! - **SHVAI/IDISVARHIGH/IDISVARLOW** — variable defined-before-use edge cases.

use super::super::CompatibilityEngine;
use mlt_core::{Diagnostic, Severity};
use tree_sitter::Node;

/// A long identifier is any `identifier` node exceeding 63 characters.
const FCLEN_MAX: usize = 63;

/// Messages for the version-gate checks.
const FCLEN_MSG: &str = "Identifiers longer than 63 characters are not supported before R2025a.";
const FCCPV_MSG: &str = "Class property validation is not available before R2017a.";
const FCDQS_MSG: &str = "Double-quoted strings are not available before R2017a. Use character vectors for scalar strings or cell arrays for string collections.";
const FCFAV_MSG: &str = "Function argument validation is not available before R2019b.";
const FCHBL_MSG: &str = "Hexadecimal and binary literals are not available before R2019b. Use 'hex2dec' and 'bin2dec' instead.";
const FCLFS_MSG: &str = "Local functions in a script are not available before R2016b.";
const FCNVA_MSG: &str = "Name=Value syntax is not available before R2021a. Use comma-separated syntax instead.";
const REDEFGI_MSG: &str = "Declaring an input or output variable to be global might not be supported in a future release.";
const REDEFGG_MSG: &str = "Declaring a variable to be global more than once might not be supported in a future release.";
const NSTIMP_MSG: &str = "Nested functions now inherit import statements from this parent function.";
const IMPIVD_MSG: &str = "Malformed import argument VAR_NAME will not be supported in a future release.";
const IMPKEY_MSG: &str = "Importing VAR_NAME will not be supported in a future release because VAR_NAME is a reserved word.";
const SHVAI_MSG: &str = "Explicitly define shared variables in the parent function before calling the nested function. MATLAB does not share uninitialized variables between a nested function and the parent function.";
const IDISVARHIGH_MSG: &str = "Variable must be explicitly defined before first use. In some cases, the definition was not required in previous releases, but it is now required.";
const IDISVARLOW_MSG: &str = "To avoid a potential conflict with functions on the path, explicitly define the variable before indexing into it.";

/// MATLAB reserved words (subset — for IMPKEY).
const RESERVED: &[&str] = &[
    "function", "end", "if", "else", "elseif", "for", "while", "switch", "case",
    "otherwise", "return", "break", "continue", "global", "persistent", "try",
    "catch", "classdef", "properties", "methods", "events", "enumeration",
    "arguments", "parfor", "spmd", "import", "true", "false",
];

