fn check_fcnva(&self, node: Node, source: &str, diagnostics: &mut Vec<Diagnostic>) {
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "=" {
            push_diag("FCNVA", FCNVA_MSG, node, Severity::Error, diagnostics);
            return;
        }
    }
}

