    /// Emit NSTIMP when a parent function's block contains an `import` command.
    fn check_function_import(
        &self,
        func: Node,
        source: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        let mut cursor = func.walk();
        for child in func.children(&mut cursor) {
            if child.kind() != "block" {
                continue;
            }
            // Look for an import command in the function's direct block
            // (excluding nested function bodies).
            if block_has_import(child, source) {
                push_diag("NSTIMP", NSTIMP_MSG, func, Severity::Warning, diagnostics);
                return;
            }
        }
    }
}

