// ---------------------------------------------------------------------------
// VarDef / VarUse
// ---------------------------------------------------------------------------

/// A single variable definition occurrence.
#[derive(Debug, Clone)]
pub struct VarDef {
    /// The variable name.
    pub name: String,
    /// How it was defined.
    pub kind: DefKind,
    /// Byte range in source.
    pub byte_range: std::ops::Range<usize>,
    /// 1-indexed line number.
    pub line: usize,
    /// 1-indexed column number.
    pub column: usize,
}

/// A single variable usage (read) occurrence.
#[derive(Debug, Clone)]
pub struct VarUse {
    /// The variable name.
    pub name: String,
    /// Byte range in source.
    pub byte_range: std::ops::Range<usize>,
    /// 1-indexed line number.
    pub line: usize,
    /// 1-indexed column number.
    pub column: usize,
}

