 * (they are declared `extern` here and satisfied at link time by the wasm
 * module's own exports). */
void *__wbindgen_malloc(size_t size);
void __wbindgen_free(void *ptr, size_t size);

void *malloc(size_t size) { return __wbindgen_malloc(size); }
void *calloc(size_t n, size_t size) {
  void *p = __wbindgen_malloc(n * size);
  if (p != 0) {
    char *q = p;
    for (size_t i = 0; i < n * size; i++) q[i] = 0;
