() => {
  const main = document.querySelector('#main, main') || document.body;
  const out = [];
  // Walk top-level sections: each category has a heading then a table.
  // Use a cursor approach: find all h2/h3 headings and the table following.
  const sections = main.querySelectorAll('h2, h3, table');
  let currentCat = '';
  let result = [];
  for (const el of sections) {
    const tag = el.tagName.toLowerCase();
    if (tag === 'h2' || tag === 'h3') {
      currentCat = el.innerText.trim();
      continue;
    }
    if (tag === 'table') {
      const rows = Array.from(el.querySelectorAll('tbody tr')).map(tr => {
        const cells = Array.from(tr.querySelectorAll('td, th')).map(td => td.innerText.trim());
        return cells;
      });
      result.push({ category: currentCat, rows });
    }
  }
  return { result, count: result.length };
}

() => {
  const main = document.querySelector('#main, main') || document.body;
  const els = main.querySelectorAll('h2, h3, table');
  let currentCat = '';
  const checks = [];
  for (const el of els) {
    const tag = el.tagName.toLowerCase();
    if (tag === 'h2' || tag === 'h3') { currentCat = el.innerText.trim(); continue; }
    if (tag === 'table') {
      for (const tr of el.querySelectorAll('tbody tr')) {
        const cells = Array.from(tr.querySelectorAll('td, th')).map(td => td.innerText.trim());
        const id = cells[0];
        if (!id || !/^[A-Za-z][A-Za-z0-9._]*$/.test(id)) continue;
        checks.push({ id, severity: cells[1] || '', message: cells[2] || '', canBeDisabled: cells[4] || '', category: currentCat });
      }
    }
  }
  return JSON.stringify({ checks, count: checks.length });
}

