import json, re
mw = {c['id']: c['message'] for c in json.load(open('.playwright-mcp/code_analyzer_checks.clean.json'))['checks']}

def toml_escape(s):
    return s.replace('\\', '\\\\').replace('"', '\\"')

def rewrite(path):
    lines = open(path).read().split('\n')
    out = []
    cur_id = None
    changed = 0
    for line in lines:
        s = line.strip()
        m_id = re.match(r'^id\s*=\s*"(.+)"$', s)
        if m_id:
            cur_id = m_id.group(1)
            out.append(line)
            continue
        m_msg = re.match(r'^message\s*=\s*"(.*)"\s*$', s)
        if m_msg and cur_id is not None:
            target = None
            if cur_id in mw:
                target = mw[cur_id]
            elif cur_id[1:] in mw and cur_id.startswith('D'):
                target = mw[cur_id[1:]]
            if target is not None:
                newline = 'message = "' + toml_escape(target) + '"'
                if newline != line:
                    out.append(newline)
                    changed += 1
                    continue
        out.append(line)
    open(path, 'w').write('\n'.join(out))
    return changed

for name in ['compatibility', 'suggested_improvements']:
    p = f'crates/mlt_rules/src/data/{name}.toml'
    c = rewrite(p)
    print(f'{name}: changed {c}')
